<div class="admin-toolbar"><form method="get" class="d-flex gap-2"><input type="hidden" name="r" value="admin/list"><input type="hidden" name="module" value="<?= e($module) ?>"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Search <?= e(strtolower($m['title'])) ?>" aria-label="Search records"><button class="btn btn-outline-primary">Search</button></form><div class="d-flex gap-2"><a class="btn btn-outline-primary" href="<?= e(url('admin/export',['module'=>$module])) ?>">Export CSV ↓</a><?php if($m['fields'] && !in_array($module,['customers','reviews'])): ?><a class="btn btn-primary" href="<?= e(url('admin/edit',['module'=>$module])) ?>">+ Add new</a><?php endif ?></div></div><?php if($module==='products'): ?><p class="admin-hint">Add products here, then configure their prices, pack sizes and stock in <a href="<?= e(url('admin/list',['module'=>'variants'])) ?>">Inventory & pack sizes</a>. Archive products to preserve order history.</p><?php endif ?><?php if($module==='variants'): ?><p class="admin-hint">Prices are shown in INR. Stock adjustments are recorded in the stock movement history.</p><?php endif ?><section class="panel table-panel"><div class="table-responsive"><table class="table admin-table"><thead><tr><?php foreach($m['columns'] as $col): ?><th><?= e(ucwords(str_replace('_',' ',$col))) ?></th><?php endforeach ?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($m['columns'] as $col): ?><td><?php if(in_array($col,['price','fixed_price'])): ?><?= money($row[$col]) ?><?php elseif($col==='active'): ?><span class="status-pill <?= !$row[$col]?'inactive':'' ?>"><?= $row[$col]?'Active':'Archived' ?></span><?php elseif($col==='stock' && $row[$col]<=(int)setting('low_stock','10')): ?><span class="low-stock"><?= (int)$row[$col] ?> · Low stock</span><?php else: ?><?= e(mb_strimwidth((string)($row[$col]??''),0,100,'…')) ?><?php endif ?></td><?php endforeach ?><td><?php if($m['fields']): ?><a class="text-link" href="<?= e(url('admin/edit',['module'=>$module,'id'=>$row['id']])) ?>">Edit</a><?php endif ?><?php if($module==='customers'): ?> <a class="text-link" href="<?= e(url('admin/customer',['id'=>$row['id']])) ?>">Orders</a><?php endif ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="<?= count($m['columns'])+1 ?>" class="empty-table">No records yet. Your store activity will appear here.</td></tr><?php endif ?></tbody></table></div></section><div class="pagination-row"><?php if($page>1): ?><a href="<?= e(url('admin/list',['module'=>$module,'q'=>$q,'page'=>$page-1])) ?>">← Previous</a><?php endif ?><span>Page <?= $page ?></span><?php if(count($rows)===30): ?><a href="<?= e(url('admin/list',['module'=>$module,'q'=>$q,'page'=>$page+1])) ?>">Next →</a><?php endif ?></div>
